; share.asm -- chapter 19: the same, and the interrupt routine prints too
; generated by gen19.py
        INCLUDE "msx.inc"
        OUTPUT "share.rom"
        ORG $4000
        CART_HEADER init
VARS    EQU RAM_START + $100    ; the program's variables: the code is in ROM
        INCLUDE "bios.inc"
IM2_TABLE EQU $C200             ; 257 bytes of $C3: every vector is $C3C3
IM2_JUMP  EQU $C3C3             ; and there, a JP to the routine
; Three texts, one in each third of the screen, printed again and again while
; the frame's interrupt comes in mode 2; its routine reads the status and
; counts the frames.
; This at sets the address with the interrupts off, and the routine
; prints the count of frames on the last row.
ticks   EQU VARS + $10          ; frames, counted by the interrupt routine
turns   EQU VARS + $12          ; turns of the main loop
which   EQU VARS + $14          ; the text being printed, 1 to 3
init:   di
        ld sp, SYS_AREA
        VDP_REG 1, $80          ; display off while the page is drawn
        VDP_REG 0, $00          ; Graphic I: 32 x 24 characters
        VDP_REG 2, $06          ; names              $1800
        VDP_REG 3, $80          ; colours            $2000
        VDP_REG 4, $00          ; patterns           $0000
        VDP_REG 5, $36          ; sprite attributes  $1B00
        VDP_REG 6, $07          ; sprite patterns    $3800
        VDP_REG 7, $0F          ; border white
        VRAM_WRITE $0000        ; the BIOS character set: 256 x 8 bytes
        ld hl, (CGTABL)
        ld bc, 2048
.font:  ld a, (hl)
        out (VDP_DATA), a
        inc hl
        dec bc
        ld a, b
        or c
        jr nz, .font
        VRAM_WRITE $0008        ; characters 1 and 2: the bit boxes
        ld hl, boxes
        ld b, 16
.box:   ld a, (hl)
        out (VDP_DATA), a
        inc hl
        djnz .box
        VRAM_WRITE $2000        ; colours: black ink (1) on white paper (15)
        ld b, 32
        ld a, $1F
.col:   out (VDP_DATA), a
        djnz .col
        VRAM_WRITE $1800        ; names: all spaces
        ld bc, 768
.clr:   ld a, ' '
        out (VDP_DATA), a
        dec bc
        ld a, b
        or c
        jr nz, .clr
        VRAM_WRITE $1B00        ; no sprites
        ld a, $D0
        out (VDP_DATA), a
        ld hl, 0
        ld (ticks), hl
        ld (turns), hl
        ld hl, IM2_TABLE        ; mode 2: the table, 257 bytes of $C3
        ld de, IM2_TABLE + 1
        ld bc, 256
        ld (hl), high IM2_JUMP
        ldir
        ld a, $C3               ; and at $C3C3, JP isr
        ld (IM2_JUMP), a
        ld hl, isr
        ld (IM2_JUMP + 1), hl
        ld a, high IM2_TABLE
        ld i, a                 ; I: the page of the table
        im 2
        VDP_REG 1, $E0          ; display on, and the frame's interrupt
        in a, (VDP_CTRL)
        ei
main:
        ld a, 1
        ld (which), a           ; which text is being printed
        ld b, 4
        ld c, 4
        ld hl, text1
        call print
        ld a, 2
        ld (which), a           ; which text is being printed
        ld b, 12
        ld c, 4
        ld hl, text2
        call print
        ld a, 3
        ld (which), a           ; which text is being printed
        ld b, 20
        ld c, 4
        ld hl, text3
        call print
        ld hl, (turns)
        inc hl
        ld (turns), hl
        jp main

; print: HL = a text ending in 0, B = row, C = column
print:  push hl
        call at                 ; the address: two OUTs
        pop hl
.next:  ld a, (hl)              ;  8
        or a                    ;  5
        ret z                   ;  6
        out (VDP_DATA), a       ; 12
        inc hl                  ;  7
        jr .next                ; 13: 51 a byte

; isr: every frame, and the count of frames, two hexadecimal digits, printed
isr:    push af
        push bc
        push hl
        in a, (VDP_CTRL)        ; the status: the VDP takes its signal down
        ld hl, (ticks)
        inc hl
        ld (ticks), hl
        ld a, l
        ld b, 23
        ld c, 0
        call puthex             ; its own address, and two bytes
        pop hl
        pop bc
        pop af
        ei
        ret
text1:        db "FIRST THIRD", 0
text2:        db "SECOND THIRD", 0
text3:        db "LAST THIRD", 0

; at: B = row (0-23), C = column (0-31) -> the VDP's write address is that
;     cell of the name table, set with the interrupts off; then they are as
;     they were. Keeps BC, DE. Uses A, F, HL.
at:     push de
        ld l, b
        ld h, 0
        add hl, hl
        add hl, hl
        add hl, hl
        add hl, hl
        add hl, hl              ; row x 32
        ld e, c
        ld d, $58               ; + $1800 + column, and bit 6 for a write
        add hl, de
        ld a, i                 ; P/V: the interrupts on or off (chapter 17)
        jp pe, .on
        ld a, i                 ; off, or one came just now: ask again
.on:    di
        ld a, l
        out (VDP_CTRL), a
        ld a, h
        out (VDP_CTRL), a       ; the two bytes, and nothing between them
        pop de
        ret po                  ; they were off: leave them off
        ei
        ret

; putc: A = character, B = row, C = column. Keeps BC, DE, HL.
putc:   push hl
        push af
        call at
        pop af
        out (VDP_DATA), a
        pop hl
        ret

; puts: HL = text ending in 0, B = row, C = column; C moves on.
puts:   ld a, (hl)
        or a
        ret z
        call putc
        inc hl
        inc c
        jr puts

; puthex: A = a byte, as two hexadecimal digits; C moves on by 2.
puthex: push af
        rrca
        rrca
        rrca
        rrca                    ; the high four bits first
        call hexdig
        pop af
hexdig: and %00001111
        add a, '0'
        cp '9' + 1
        jr c, .digit
        add a, 'A' - '9' - 1    ; 10-15 become A-F
.digit: call putc
        inc c
        ret
boxes:                          ; characters 1 (empty box) and 2 (filled)
        db %11111110, %10000010, %10000010, %10000010, %10000010, %10000010, %11111110, %00000000
        db %11111110, %11111110, %11111110, %11111110, %11111110, %11111110, %11111110, %00000000
        ASSERT $ <= $8000, the program is longer than the cartridge
        ds $8000 - $, $FF       ; pad the cartridge to 16 KB
